def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full, nonzero divider row or column.
    for r in range(h):
        if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            n = min(len(top), len(bottom))
            return [
                [2 if top[i][c] != 0 and bottom[i][c] != 0 else 0
                 for c in range(w)]
                for i in range(n)
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left_w, right_w = c, w - c - 1
            n = min(left_w, right_w)
            return [
                [2 if grid[r][i] != 0 and grid[r][c + 1 + i] != 0 else 0
                 for i in range(n)]
                for r in range(h)
            ]

    return [row[:] for row in grid]
